#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;
int main(){for(auto [m,k]: vector<pair<int,int>>{{2,3},{3,2},{3,3},{2,4}}){int n=m*k+1,E=n-1; vector<pair<int,int>> ed;for(int a=0;a<m;a++)for(int j=0;j<k;j++)ed.push_back({j?1+a*k+j-1:0,1+a*k+j});vector<int> adj(n);for(auto [u,v]:ed)adj[u]|=1<<v,adj[v]|=1<<u;vector<vector<int>> outs(1<<E,vector<int>(n));for(int o=0;o<(1<<E);o++)for(int e=0;e<E;e++){auto [u,v]=ed[e];if(o>>e&1)swap(u,v);outs[o][u]|=1<<v;}vector<int> best(1<<E,n+1),col(n),cls(n);long long partitions=0;auto rec=[&](auto&&self,int v,int nc)->void{if(v==n){partitions++;for(int o=0;o<(1<<E);o++){if(best[o]<=nc)continue;bool good=true;for(int u=0;u<n&&good;u++){if(outs[o][u]==0)continue;bool ok=false;for(int c=0;c<nc;c++)if((outs[o][u]&cls[c])==cls[c]){ok=true;break;}good=ok;}if(good)best[o]=nc;}return;}for(int c=0;c<=nc;c++){if(adj[v]&cls[c])continue;cls[c]|=1<<v;col[v]=c;self(self,v+1,nc+(c==nc));cls[c]^=1<<v;}};rec(rec,0,0);cout<<"m="<<m<<" k="<<k<<" vertices="<<n<<" orientations="<<(1<<E)<<" proper_partitions="<<partitions<<" min="<<*min_element(best.begin(),best.end())<<" max="<<*max_element(best.begin(),best.end())<<" conjectured_min="<<3+m*(k/2-1)<<" conjectured_max="<<m*(k-1)+2<<"\n";}}
